<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
type Dataset={id:string;name:string;sql:string};type Style={bold?:boolean;color?:string;background?:string;align?:string};type Binding={datasetId:string;field:string;expansion:'NONE'|'DOWN'|'RIGHT';groupBy?:string;aggregate:'NONE'|'SUM'|'COUNT';regionId?:string};type Cell={row:number;column:number;value:string;style?:Style;binding?:Binding};type Merge={startRow:number;startColumn:number;endRow:number;endColumn:number};type Definition={rows:number;columns:number;cells:Cell[];merges:Merge[];rowHeights:Record<number,number>;columnWidths:Record<number,number>};type Template={id:string;name:string;definition:Definition};type SheetData=Definition&{cells:Array<Cell&{value:unknown}>}
const blank=():Definition=>({rows:12,columns:6,cells:[{row:0,column:0,value:'销售明细',style:{bold:true,background:'#dbeafe'}},{row:2,column:0,value:'地区'},{row:2,column:1,value:'金额'}],merges:[{startRow:0,startColumn:0,endRow:0,endColumn:2}],rowHeights:{0:46},columnWidths:{0:140,1:120}})
const apiKey=ref(sessionStorage.getItem('smartbi.apiKey')||''),datasets=ref<Dataset[]>([]),templates=ref<Template[]>([]),currentId=ref(''),name=ref('销售报表'),mode=ref<'design'|'preview'>('design'),notice=ref(''),error=ref(''),parameters=ref('{"minimum":100}'),rendered=ref<SheetData|null>(null),selected=reactive({row:0,column:0}),definition=reactive<Definition>(blank())
const edit=reactive({value:'',bold:false,background:'#ffffff',datasetId:'',field:'',expansion:'NONE' as Binding['expansion'],groupBy:'',aggregate:'NONE' as Binding['aggregate'],regionId:'',rowHeight:35,columnWidth:112})
const selectedCell=computed(()=>definition.cells.find(c=>c.row===selected.row&&c.column===selected.column))
async function api(path:string,init?:RequestInit){sessionStorage.setItem('smartbi.apiKey',apiKey.value);const response=await fetch(path,{...init,headers:{'Content-Type':'application/json','X-API-Key':apiKey.value,...init?.headers}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.message||`HTTP ${response.status}`);return body}
async function load(){await act(async()=>{[datasets.value,templates.value]=await Promise.all([api('/api/v1/datasets'),api('/api/v1/report-templates')]);notice.value='资源已加载'})}
function choose(row:number,column:number){selected.row=row;selected.column=column;const cell=cellAt(row,column);edit.value=cell?.value||'';edit.bold=!!cell?.style?.bold;edit.background=cell?.style?.background||'#ffffff';edit.datasetId=cell?.binding?.datasetId||'';edit.field=cell?.binding?.field||'';edit.expansion=cell?.binding?.expansion||'NONE';edit.groupBy=cell?.binding?.groupBy||'';edit.aggregate=cell?.binding?.aggregate||'NONE';edit.regionId=cell?.binding?.regionId||'';edit.rowHeight=definition.rowHeights[row]||35;edit.columnWidth=definition.columnWidths[column]||112}
function apply(){let cell=selectedCell.value;if(!cell){cell={row:selected.row,column:selected.column,value:''};definition.cells.push(cell)}cell.value=edit.value;cell.style={bold:edit.bold,background:edit.background};cell.binding=edit.datasetId&&edit.field?{datasetId:edit.datasetId,field:edit.field,expansion:edit.expansion,groupBy:edit.groupBy||undefined,aggregate:edit.aggregate,regionId:edit.regionId||undefined}:undefined;definition.rowHeights[selected.row]=clamp(edit.rowHeight,24,160);definition.columnWidths[selected.column]=clamp(edit.columnWidth,60,400)}
function clamp(value:number,min:number,max:number){return Math.min(max,Math.max(min,Number(value)||min))}function cellAt(row:number,column:number){return definition.cells.find(x=>x.row===row&&x.column===column)}function label(column:number){let value='';for(let n=column+1;n;n=Math.floor((n-1)/26))value=String.fromCharCode(65+(n-1)%26)+value;return value}
function normalize(value:Definition){return {...value,cells:value.cells||[],merges:value.merges||[],rowHeights:value.rowHeights||{},columnWidths:value.columnWidths||{}}}
async function save(){apply();await act(async()=>{const body=JSON.stringify({name:name.value,definition});const template=await api(currentId.value?`/api/v1/report-templates/${currentId.value}`:'/api/v1/report-templates',{method:currentId.value?'PUT':'POST',body});currentId.value=template.id;notice.value='模板已保存，可重新打开';await load()})}
function open(template:Template){currentId.value=template.id;name.value=template.name;Object.assign(definition,JSON.parse(JSON.stringify(normalize(template.definition))));mode.value='design';choose(0,0)}
function createNew(){currentId.value='';name.value='新报表';Object.assign(definition,blank());rendered.value=null;mode.value='design';choose(0,0)}
async function preview(){if(!currentId.value)await save();await act(async()=>{rendered.value=await api(`/api/v1/report-templates/${currentId.value}/render`,{method:'POST',body:JSON.stringify({parameters:JSON.parse(parameters.value)})});mode.value='preview';notice.value='服务端确定性渲染完成'})}
function mergeAt(data:{merges:Merge[]},row:number,column:number){return data.merges.find(m=>row>=m.startRow&&row<=m.endRow&&column>=m.startColumn&&column<=m.endColumn)}function covered(data:{merges:Merge[]},row:number,column:number){const merge=mergeAt(data,row,column);return !!merge&&(merge.startRow!==row||merge.startColumn!==column)}
function position(data:{merges:Merge[]},row:number,column:number){const merge=mergeAt(data,row,column);return {gridRow:`${row+2} / span ${merge?merge.endRow-merge.startRow+1:1}`,gridColumn:`${column+2} / span ${merge?merge.endColumn-merge.startColumn+1:1}`}}
function columns(data:{columns:number;columnWidths:Record<number,number>}){return `42px ${Array.from({length:data.columns},(_,i)=>`${data.columnWidths?.[i]||112}px`).join(' ')}`}function rows(data:{rows:number;rowHeights:Record<number,number>}){return `32px ${Array.from({length:data.rows},(_,i)=>`${data.rowHeights?.[i]||35}px`).join(' ')}`}
function renderedAt(row:number,column:number){return rendered.value?.cells.find(x=>x.row===row&&x.column===column)}
function mergeRight(){definition.merges=definition.merges.filter(m=>!(selected.row>=m.startRow&&selected.row<=m.endRow&&selected.column>=m.startColumn&&selected.column<=m.endColumn));if(selected.column<definition.columns-1)definition.merges.push({startRow:selected.row,startColumn:selected.column,endRow:selected.row,endColumn:selected.column+1})}
function unmerge(){definition.merges=definition.merges.filter(m=>!(selected.row>=m.startRow&&selected.row<=m.endRow&&selected.column>=m.startColumn&&selected.column<=m.endColumn))}
async function act(fn:()=>Promise<void>){error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}}onMounted(load)
</script>
<template><main><header><div><span class="eyebrow">SMARTBI SPREADSHEET REPORT</span><h1>电子表格报表设计器</h1><p>统一绑定区域、确定性扩展与布局后公式计算。</p></div><div class="auth"><input v-model="apiKey" type="password" placeholder="API Key"><button class="ghost" @click="load">加载</button></div></header><p v-if="error" class="error">{{error}}</p><p v-if="notice" class="success">{{notice}}</p><nav><button :class="{active:mode==='design'}" @click="mode='design'">设计态</button><button :class="{active:mode==='preview'}" @click="preview">预览态</button><input v-model="name" aria-label="模板名称"><button @click="save">保存模板</button></nav>
<section class="workspace"><aside><h2>模板</h2><button class="wide ghost" @click="createNew">新建</button><button v-for="template in templates" :key="template.id" class="template" @click="open(template)">{{template.name}}</button><h2>渲染参数</h2><textarea v-model="parameters" rows="5"/></aside>
<div class="sheet-wrap"><div v-if="mode==='design'" class="sheet" data-testid="design-sheet" :style="{gridTemplateColumns:columns(definition),gridTemplateRows:rows(definition)}"><div class="corner"></div><div v-for="column in definition.columns" :key="`h${column}`" class="head column-head" :style="{gridColumn:column+1,gridRow:1}">{{label(column-1)}}</div><div v-for="row in definition.rows" :key="`r${row}`" class="head row-head" :style="{gridColumn:1,gridRow:row+1}">{{row}}</div><template v-for="row in definition.rows" :key="`cells-${row}`"><button v-for="column in definition.columns" v-show="!covered(definition,row-1,column-1)" :key="column" class="cell" :class="{selected:selected.row===row-1&&selected.column===column-1,bound:cellAt(row-1,column-1)?.binding,merged:mergeAt(definition,row-1,column-1)}" :style="{...position(definition,row-1,column-1),...cellAt(row-1,column-1)?.style}" @click="choose(row-1,column-1)">{{cellAt(row-1,column-1)?.value}}</button></template></div>
<div v-else-if="rendered" class="sheet" data-testid="preview-sheet" :style="{gridTemplateColumns:columns(rendered),gridTemplateRows:rows(rendered)}"><div class="corner"></div><div v-for="column in rendered.columns" :key="`ph${column}`" class="head" :style="{gridColumn:column+1,gridRow:1}">{{label(column-1)}}</div><div v-for="row in rendered.rows" :key="`pr${row}`" class="head" :style="{gridColumn:1,gridRow:row+1}">{{row}}</div><template v-for="row in rendered.rows" :key="`pc${row}`"><div v-for="column in rendered.columns" v-show="!covered(rendered,row-1,column-1)" :key="column" class="cell preview" :class="{merged:mergeAt(rendered,row-1,column-1)}" :style="{...position(rendered,row-1,column-1),...renderedAt(row-1,column-1)?.style}">{{renderedAt(row-1,column-1)?.value}}</div></template></div></div>
<aside v-if="mode==='design'" class="inspector"><h2>单元格 {{label(selected.column)}}{{selected.row+1}}</h2><label>内容 / 公式<input v-model="edit.value" placeholder="文本、=A1+B1 或 =SUM(A1:A9)"></label><div class="row"><label><input v-model="edit.bold" type="checkbox"> 粗体</label><label>底色<input v-model="edit.background" type="color"></label></div><div class="row"><label>行高<input v-model.number="edit.rowHeight" type="number" min="24" max="160"></label><label>列宽<input v-model.number="edit.columnWidth" type="number" min="60" max="400"></label></div><div class="row"><button class="ghost wide" @click="mergeRight">向右合并</button><button class="ghost wide" @click="unmerge">取消合并</button></div><h2>数据集绑定</h2><label>数据集<select v-model="edit.datasetId"><option value="">无</option><option v-for="dataset in datasets" :key="dataset.id" :value="dataset.id">{{dataset.name}}</option></select></label><label>字段<input v-model="edit.field" placeholder="region"></label><label>扩展<select v-model="edit.expansion"><option value="NONE">不扩展</option><option value="DOWN">纵向</option><option value="RIGHT">横向</option></select></label><label v-if="edit.expansion!=='NONE'">区域 ID<input v-model="edit.regionId" placeholder="detail（同区域字段保持对齐）"></label><label>汇总<select v-model="edit.aggregate"><option value="NONE">无</option><option value="SUM">SUM</option><option value="COUNT">COUNT</option></select></label><label v-if="edit.aggregate!=='NONE'">分组字段<input v-model="edit.groupBy"></label><button class="wide" @click="apply">应用单元格</button></aside></section></main></template>
